#include "unity.h"
#include "mpu6050.h"

#include <string.h>

static uint8_t callback_bytes[6];
static bool callback_result;
static unsigned int callback_calls;
static uint8_t callback_address;
static uint8_t callback_register;
static uint16_t callback_length;
static bool callback_received_nonnull_bytes;

static bool read_callback(uint8_t address, uint8_t reg, uint8_t *bytes, uint16_t length)
{
    callback_calls++;
    callback_address = address;
    callback_register = reg;
    callback_length = length;
    callback_received_nonnull_bytes = (bytes != NULL);

    if ((bytes != NULL) && (length >= sizeof(callback_bytes)))
    {
        memcpy(bytes, callback_bytes, sizeof(callback_bytes));
    }

    return callback_result;
}

void setUp(void)
{
    memset(callback_bytes, 0, sizeof(callback_bytes));
    callback_result = true;
    callback_calls = 0U;
    callback_address = 0U;
    callback_register = 0U;
    callback_length = 0U;
    callback_received_nonnull_bytes = false;
}

