void test_mpu6050_read_01(void)
{
    mpu6050_sample_t sample = {1.0F, 2.0F, 3.0F};

    TEST_ASSERT_FALSE(mpu6050_read(NULL, &sample));
    TEST_ASSERT_EQUAL_INT(0, callback_calls);
    TEST_ASSERT_FLOAT_WITHIN(0.00001F, 1.0F, sample.x_g);
    TEST_ASSERT_FLOAT_WITHIN(0.00001F, 2.0F, sample.y_g);
    TEST_ASSERT_FLOAT_WITHIN(0.00001F, 3.0F, sample.z_g);
}

