void test_mpu6050_read_05(void)
{
    const mpu6050_io_t io = {read_callback, NULL, 0x68U};
    mpu6050_sample_t sample = {0.0F, 0.0F, 0.0F};

    callback_bytes[0] = 0x10U;
    callback_bytes[1] = 0x00U; /* 4096 => 0.5 g */
    callback_bytes[2] = 0xF0U;
    callback_bytes[3] = 0x00U; /* -4096 => -0.5 g */
    callback_bytes[4] = 0x20U;
    callback_bytes[5] = 0x00U; /* 8192 => 1 g */

    TEST_ASSERT_TRUE(mpu6050_read(&io, &sample));
    TEST_ASSERT_EQUAL_INT(1, callback_calls);
    TEST_ASSERT_EQUAL_INT(0x68, callback_address);
    TEST_ASSERT_EQUAL_INT(6, callback_length);
    TEST_ASSERT_TRUE(callback_received_nonnull_bytes);
    TEST_ASSERT_FLOAT_WITHIN(0.00001F, 0.5F, sample.x_g);
    TEST_ASSERT_FLOAT_WITHIN(0.00001F, -0.5F, sample.y_g);
    TEST_ASSERT_FLOAT_WITHIN(0.00001F, 1.0F, sample.z_g);
}

void test_mpu6050_read_06(void)
{
    const mpu6050_io_t io = {read_callback, NULL, 0x68U};
    mpu6050_sample_t sample = {0.0F, 0.0F, 0.0F};

    /* Exercise raw values on both sides of the signed-conversion boundary. */
    callback_bytes[0] = 0x7FU;
    callback_bytes[1] = 0xFFU; /* 32767 */
    callback_bytes[2] = 0x80U;
    callback_bytes[3] = 0x00U; /* 32768 */
    callback_bytes[4] = 0xFFU;
    callback_bytes[5] = 0xFFU; /* 65535 */

    TEST_ASSERT_TRUE(mpu6050_read(&io, &sample));
    TEST_ASSERT_FLOAT_WITHIN(0.00001F, 32767.0F / 8192.0F, sample.x_g);
    TEST_ASSERT_FLOAT_WITHIN(0.00001F, -4.0F, sample.y_g);
    TEST_ASSERT_FLOAT_WITHIN(0.00001F, -1.0F / 8192.0F, sample.z_g);
}
